var i=200;var a=[{id:`cooking-200-01`,theoryId:200,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What creates the foam in a basic meringue?`,ua:`Що утворює піну в базовій мерензі?`},explanation:{en:`Whisking spreads air bubbles through proteins in egg whites.`,ua:`Збивання розподіляє повітряні бульбашки у структурі яєчних білків.`},options:[{id:`a`,text:{en:`Whipping air into egg whites`,ua:`Збивання повітря в яєчні білки`}},{id:`b`,text:{en:`Boiling flour in salt water`,ua:`Варіння борошна в солоній воді`}},{id:`c`,text:{en:`Freezing whole eggs before whisking`,ua:`Заморожування цілих яєць перед збиванням`}}],answer:{optionIds:[`a`]}},{id:`cooking-200-02`,theoryId:200,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Grease or egg yolk contamination can interfere with stable egg-white foaming.`,ua:`Жир або домішки жовтка можуть заважати утворенню стабільної піни з білків.`},explanation:{en:`Fat disrupts foam formation; clean bowls and utensils improve results.`,ua:`Жир заважає піноутворенню; чисті миски й інструменти покращують результат.`},answer:{value:!0}},{id:`cooking-200-03`,theoryId:200,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match meringue ingredients or steps to functions.`,ua:`Поєднайте складники чи етапи меренги з функціями.`},explanation:{en:`Foam quality depends on protein, air, sugar and processing.`,ua:`Якість піни залежить від білків, повітря, цукру та обробки.`},leftItems:[{id:`l1`,text:{en:`Egg whites`,ua:`Яєчні білки`}},{id:`l2`,text:{en:`Sugar`,ua:`Цукор`}},{id:`l3`,text:{en:`Small amount of acid`,ua:`Невелика кількість кислоти`}}],rightItems:[{id:`r1`,text:{en:`Form a protein film around air bubbles`,ua:`Створюють білкову плівку навколо бульбашок повітря`}},{id:`r3`,text:{en:`Can support foam stability`,ua:`Може покращити стабільність піни`}},{id:`r2`,text:{en:`Supports foam stability and sweetness`,ua:`Допомагає стабілізувати піну й додає солодкість`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-200-04`,theoryId:200,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Your egg-white foam looks dry and clumpy from excessive beating. What is the best prevention next time?`,ua:`Білкова піна стала сухою та грудкуватою від надмірного збивання. Як запобігти цьому?`},explanation:{en:`Overwhipping destabilizes the foam and reduces usability.`,ua:`Надмірне збивання робить піну нестабільною та незручною в роботі.`},options:[{id:`a`,text:{en:`Add vegetable oil to the bowl before whipping`,ua:`Додавати олію в миску перед збиванням`}},{id:`b`,text:{en:`Stop at the peaks required by the recipe`,ua:`Зупинятися на піках, потрібних рецептурі`}},{id:`c`,text:{en:`Keep beating at full speed for another ten minutes`,ua:`Збивати ще десять хвилин на максимальній швидкості`}}],answer:{optionIds:[`b`]}},{id:`cooking-200-05`,theoryId:200,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which practices can support meringue stability?`,ua:`Які дії можуть підвищити стабільність меренги?`},explanation:{en:`Foam quality depends on clean tools and controlled whipping.`,ua:`Якість піни залежить від чистоти інструментів та контрольованого збивання.`},options:[{id:`a`,text:{en:`Keep whipping long after the foam breaks`,ua:`Продовжувати збивати ще довго після руйнування піни`}},{id:`b`,text:{en:`Add sugar as the chosen method directs`,ua:`Додавати цукор за обраною технологією`}},{id:`c`,text:{en:`Use a clean, grease-free bowl`,ua:`Використовувати чисту миску без жиру`}},{id:`d`,text:{en:`Use a modest acid stabilizer if prescribed`,ua:`Застосувати невелику кількість кислоти, якщо передбачено рецептом`}}],answer:{optionIds:[`b`,`c`,`d`]}}];var n={theoryId:200,exercises:a};export{n as default,a as exercises,i as theoryId};